    font-family: var(--cc-font-family);
    color: var(--cc-color-text);
    background: var(--cc-color-background);
  }

  .banner {
    position: relative;
    isolation: isolate;
    display: flex;
    align-items: center;
    width: 100%;
    height: 168px;
    overflow: hidden;
    padding: var(--cc-space-l) var(--cc-space-xl);
