  }

  .banner::before {
    position: absolute;
    z-index: -1;
    inset: 0;
    content: "";
    background: linear-gradient(
      115deg,
      color-mix(in srgb, var(--cc-color-primary) 46%, var(--cc-color-border)),
      var(--cc-color-primary)
    );
    filter: brightness(.58) saturate(1.18);
  }

  .icon {
    flex: 0 0 auto;
    width: 88px;
    height: 88px;
    color: var(--cc-color-text);
  }

  .content {
    min-width: 0;
  }

  .title {
    margin: 0 0 var(--cc-space-s);
    font-size: 1.5rem;
    line-height: 1.2;
    font-weight: 600;
    color: var(--cc-color-text);
  }

  .description {
    max-width: 78rem;
    margin: 0;
    font-size: 0.875rem;
    line-height: 1.5;
    font-weight: 400;
    color: var(--cc-color-text);
    opacity: .78;
  }

  @media (max-width: 40rem) {
    .banner {
      padding: var(--cc-space-l);
      gap: var(--cc-space-m);
    }

    .icon {
      width: 64px;
      height: 64px;
    }
  }
</style>
</head>
