  body {
    margin: 0;
    padding: var(--cc-space-l);
    box-sizing: border-box;
    font-family: var(--cc-font-family);
    color: var(--cc-color-text);
    background: var(--cc-color-background);
  }

  *, *::before, *::after {
    box-sizing: border-box;
  }

  .caption {
    height: 24px;
    margin: 0 0 var(--cc-space-m) 0;
    overflow: hidden;
    color: var(--cc-color-text);
    font-size: 0.75rem;
    line-height: 1.4;
    text-overflow: ellipsis;
    white-space: nowrap;
    opacity: 0.75;
  }

  .caption strong {
    font-weight: 600;
    opacity: 1;
  }

  .pyramid {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--cc-space-xs);
    isolation: isolate;
  }

  .tier {
    position: relative;
    overflow: visible;
    color: var(--cc-color-text);
  }

  .tier-top {
    z-index: 1;
    width: 34%;
    height: 110px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: var(--cc-space-s) var(--cc-space-m);
    overflow: hidden;
    text-align: center;
    background: linear-gradient(135deg, var(--cc-vis-4), var(--cc-vis-3));
    clip-path: polygon(8% 0%, 92% 0%, 100% 100%, 0% 100%);
    border-radius: var(--cc-radius) var(--cc-radius) 0 0;
  }

  .tier-recommendations {
    z-index: 2;
    width: 67%;
    height: 140px;
  }

  .tier-assets {
    z-index: 3;
    width: 100%;
    height: 150px;
  }

  .recommendation-segments,
  .asset-segments {
    position: absolute;
    inset: 0;
    display: flex;
    width: 100%;
    height: 100%;
  }

  .segment {
    position: relative;
    z-index: 1;
    min-width: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    container-type: inline-size;
    outline: none;
  }

  .segment:hover,
  .segment:focus,
  .segment:focus-visible {
    z-index: 20;
  }

  .segment:focus-visible .segment-card {
    outline: 2px solid var(--cc-color-primary);
    outline-offset: 2px;
  }

  .segment-fill {
    position: absolute;
    inset: 0;
    z-index: -1;
    border-right: 2px solid var(--cc-color-background);
  }

  .segment:last-child .segment-fill {
    border-right: 0;
  }

  .recommendation-segments .segment:first-child .segment-fill {
    clip-path: polygon(4% 0%, 100% 0%, 100% 100%, 0% 100%);
  }

  .recommendation-segments .segment:last-child .segment-fill {
    clip-path: polygon(0% 0%, 96% 0%, 100% 100%, 0% 100%);
  }

  .recommendation-segments .segment:only-child .segment-fill {
    clip-path: polygon(4% 0%, 96% 0%, 100% 100%, 0% 100%);
  }

  .asset-segments .segment:first-child .segment-fill {
    clip-path: polygon(2% 0%, 100% 0%, 100% 100%, 0% 100%);
    border-radius: 0 0 0 var(--cc-radius);
  }

  .asset-segments .segment:last-child .segment-fill {
    clip-path: polygon(0% 0%, 98% 0%, 100% 100%, 0% 100%);
    border-radius: 0 0 var(--cc-radius) 0;
  }

  .asset-segments .segment:only-child .segment-fill {
    clip-path: polygon(2% 0%, 98% 0%, 100% 100%, 0% 100%);
    border-radius: 0 0 var(--cc-radius) var(--cc-radius);
  }

  .recommendation-segments .segment:nth-child(4n + 1) .segment-fill { background: var(--cc-vis-1); }
  .recommendation-segments .segment:nth-child(4n + 2) .segment-fill { background: var(--cc-vis-0); }
  .recommendation-segments .segment:nth-child(4n + 3) .segment-fill { background: var(--cc-vis-6); }
  .recommendation-segments .segment:nth-child(4n + 4) .segment-fill { background: var(--cc-vis-9); }

  .asset-segments .segment:nth-child(4n + 1) .segment-fill { background: var(--cc-vis-2); }
  .asset-segments .segment:nth-child(4n + 2) .segment-fill { background: var(--cc-vis-5); }
  .asset-segments .segment:nth-child(4n + 3) .segment-fill { background: var(--cc-vis-8); }
  .asset-segments .segment:nth-child(4n + 4) .segment-fill { background: var(--cc-vis-3); }

  .tier-heading {
    position: absolute;
    z-index: 10;
    top: var(--cc-space-s);
    left: 50%;
    max-width: calc(100% - var(--cc-space-xl));
    padding: var(--cc-space-xs) var(--cc-space-s);
    transform: translateX(-50%);
    border-radius: var(--cc-radius-s);
    background: color-mix(in srgb, var(--cc-color-background) 86%, transparent);
    color: var(--cc-color-text);
    font-size: 0.75rem;
    font-weight: 600;
    line-height: 1.4;
    text-align: center;
    white-space: nowrap;
    pointer-events: none;
  }

  .segment-card {
    position: relative;
    z-index: 2;
    width: calc(100% - var(--cc-space-m));
    min-width: 0;
    margin-top: var(--cc-space-xl);
    padding: var(--cc-space-s);
    overflow: hidden;
    border: 1px solid color-mix(in srgb, var(--cc-color-border) 75%, transparent);
    border-radius: var(--cc-radius-s);
    background: color-mix(in srgb, var(--cc-color-background) 82%, transparent);
    color: var(--cc-color-text);
    text-align: left;
  }

  .segment-label,
  .segment-value,
  .segment-context {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .segment-label {
    font-size: 0.75rem;
    font-weight: 600;
    line-height: 1.4;
  }

  .segment-value {
    margin-top: var(--cc-space-xs);
    font-size: 1.5rem;
    font-weight: 600;
    line-height: 1.2;
  }

  .segment-context {
    margin-top: var(--cc-space-xs);
    font-size: 0.75rem;
    line-height: 1.4;
    opacity: 0.78;
  }

  .segment-tooltip {
    position: absolute;
    z-index: 30;
    bottom: calc(100% + var(--cc-space-s));
    left: 50%;
    width: min(18rem, calc(100vw - 2 * var(--cc-space-l)));
    padding: var(--cc-space-m);
    transform: translate(-50%, var(--cc-space-xs));
    visibility: hidden;
    opacity: 0;
    border: 1px solid var(--cc-color-border);
    border-radius: var(--cc-radius);
    background: var(--cc-color-surface);
    color: var(--cc-color-text);
    box-shadow:
      0 var(--cc-space-xs) var(--cc-space-m)
      color-mix(in srgb, var(--cc-color-text) 18%, transparent);
    pointer-events: none;
  }

  .segment:hover .segment-tooltip,
  .segment:focus .segment-tooltip,
  .segment:focus-visible .segment-tooltip {
    visibility: visible;
    opacity: 1;
    transform: translate(-50%, 0);
  }

  .tooltip-label {
    display: block;
    overflow-wrap: anywhere;
    font-size: 0.875rem;
    font-weight: 600;
    line-height: 1.4;
  }

  .tooltip-metric {
    display: flex;
    align-items: baseline;
    gap: var(--cc-space-xs);
    margin-top: var(--cc-space-s);
  }

  .tooltip-count {
    font-size: 1.5rem;
    font-weight: 600;
    line-height: 1.2;
  }

  .tooltip-context,
  .tooltip-share {
    font-size: 0.75rem;
    line-height: 1.4;
  }

  .tooltip-context {
    opacity: 0.8;
  }

  .tooltip-share {
    display: block;
    margin-top: var(--cc-space-xs);
    color: var(--cc-color-text);
    opacity: 0.72;
  }

  .band-label {
    padding: var(--cc-space-xs) var(--cc-space-s);
    border-radius: var(--cc-radius-s);
    background: color-mix(in srgb, var(--cc-color-background) 76%, transparent);
    color: var(--cc-color-text);
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
  }

  .band-number {
    margin: var(--cc-space-xs) 0;
    padding: 0 var(--cc-space-s);
    border-radius: var(--cc-radius-s);
    background: color-mix(in srgb, var(--cc-color-background) 76%, transparent);
    color: var(--cc-color-text);
    font-size: 1.5rem;
    font-weight: 600;
    line-height: 1.2;
  }

  .band-desc {
    max-width: 100%;
    padding: var(--cc-space-xs) var(--cc-space-s);
    border-radius: var(--cc-radius-s);
    background: color-mix(in srgb, var(--cc-color-background) 76%, transparent);
    color: var(--cc-color-text);
    font-size: 0.75rem;
    line-height: 1.4;
  }

  .empty {
    height: 432px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: var(--cc-space-m);
    color: var(--cc-color-text);
    font-size: 0.875rem;
    opacity: 0.7;
  }

  @container (max-width: 149px) {
    .segment-card {
      display: flex;
      align-items: center;
      gap: var(--cc-space-xs);
      padding: var(--cc-space-xs);
      text-align: center;
    }

    .segment-value {
      flex: 0 0 auto;
      margin-top: 0;
      font-size: 0.875rem;
    }

    .segment-label {
      min-width: 0;
      flex: 1 1 auto;
      font-weight: 600;
    }

    .segment-context {
      display: none;
    }
  }

  @container (max-width: 71px) {
    .segment-card {
      display: none;
    }
  }

  @media (max-width: 700px) {
    .tier-top {
      width: 48%;
    }

    .tier-recommendations {
      width: 76%;
    }

    .tier-heading {
      max-width: calc(100% - var(--cc-space-l));
      white-space: normal;
    }

    .band-desc {
      display: none;
    }
  }
</style>

{% if rows.size == 0 %}
  <div class="empty">No insight pyramid data available.</div>
{% else %}
  {% assign level1_total = 0 %}
  {% assign level2_total = 0 %}
  {% assign level3_total = 0 %}

  {% for row in rows %}
    {% if row["level"].value == 1 %}
      {% assign level1_total = level1_total | plus: row["item_count"].value %}
    {% elsif row["level"].value == 2 %}
      {% assign level2_total = level2_total | plus: row["item_count"].value %}
    {% elsif row["level"].value == 3 %}
      {% assign level3_total = level3_total | plus: row["item_count"].value %}
    {% endif %}
  {% endfor %}

  <p class="caption">
    <strong>Layered insight architecture:</strong> observed assets feed category recommendations, which roll up into a concise agent summary.
  </p>

  <div class="pyramid">
    <div class="tier tier-top">
      <div class="band-label">Level 1 · Agent Summaries</div>
      <div class="band-number">{{ level1_total }}</div>
      <div class="band-desc">
        {% if level1_total == 1 %}Agent summary{% else %}Agent summaries{% endif %}
      </div>
    </div>

    <div class="tier tier-recommendations">
      <div class="tier-heading">Level 2 · Recommendations by Category · {{ level2_total }} total</div>
      <div class="recommendation-segments">
        {% for row in rows %}
          {% if row["level"].value == 2 %}
            {% assign human_label = row["item_label"].value | replace: "_", " " | replace: "-", " " | capitalize %}
            {% assign level_share = 0 %}
            {% if level2_total > 0 %}
              {% assign level_share = row["item_count"].value | times: 100.0 | divided_by: level2_total %}
            {% endif %}
            <div
              class="segment"
              style="flex-grow: {{ row["item_count"].value }}; flex-basis: 0;"
              tabindex="0"
              role="img"
              aria-label="{{ human_label }}: {{ row["item_count"].value }} recommendations, {{ level_share | round: 1 }} percent of Level 2"
              title="{{ human_label }}: {{ row["item_count"].value }} recommendations">
              <div class="segment-fill"></div>
              <div class="segment-card">
                <span class="segment-label">{{ human_label }}</span>
                <span class="segment-value">{{ row["item_count"].value }}</span>
                <span class="segment-context">recommendations</span>
              </div>
              <div class="segment-tooltip" role="tooltip">
                <span class="tooltip-label">{{ human_label }}</span>
                <span class="tooltip-metric">
                  <span class="tooltip-count">{{ row["item_count"].value }}</span>
                  <span class="tooltip-context">recommendations</span>
                </span>
                {% if level2_total > 0 %}
                  <span class="tooltip-share">{{ level_share | round: 1 }}% of Level 2 recommendations</span>
                {% endif %}
              </div>
            </div>
          {% endif %}
        {% endfor %}
      </div>
    </div>

    <div class="tier tier-assets">
      <div class="tier-heading">Level 3 · Observed Assets by Resource Type · {{ level3_total }} total</div>
      <div class="asset-segments">
        {% for row in rows %}
          {% if row["level"].value == 3 %}
            {% assign human_label = row["item_label"].value | replace: "_", " " | replace: "-", " " | capitalize %}
            {% assign level_share = 0 %}
            {% if level3_total > 0 %}
              {% assign level_share = row["item_count"].value | times: 100.0 | divided_by: level3_total %}
            {% endif %}
            <div
              class="segment"
              style="flex-grow: {{ row["item_count"].value }}; flex-basis: 0;"
              tabindex="0"
              role="img"
              aria-label="{{ human_label }}: {{ row["item_count"].value }} distinct assets, {{ level_share | round: 1 }} percent of Level 3"
              title="{{ human_label }}: {{ row["item_count"].value }} distinct assets">
              <div class="segment-fill"></div>
              <div class="segment-card">
                <span class="segment-label">{{ human_label }}</span>
                <span class="segment-value">{{ row["item_count"].value }}</span>
                <span class="segment-context">distinct assets</span>
              </div>
              <div class="segment-tooltip" role="tooltip">
                <span class="tooltip-label">{{ human_label }}</span>
                <span class="tooltip-metric">
                  <span class="tooltip-count">{{ row["item_count"].value }}</span>
                  <span class="tooltip-context">distinct assets</span>
                </span>
                {% if level3_total > 0 %}
                  <span class="tooltip-share">{{ level_share | round: 1 }}% of Level 3 observed assets</span>
                {% endif %}
              </div>
            </div>
          {% endif %}
        {% endfor %}
      </div>
    </div>
  </div>
{% endif %}"},"panelIndex":"de316231-7612-426b-9a05-0cfc9c4482e0","gridData":{"y":6,"x":0,"w":48,"h":18,"i":"de316231-7612-426b-9a05-0cfc9c4482e0","sectionId":"a0e6de58-2f37-4114-9522-9a9cdae9aba9"}},{"type":"custom_content","embeddableConfig":{"esql_query":["FROM aws-cockpit-insight-summary
